package main

import (
	"errors"
	"fmt"
)

// Sentinel error: a package-level value compared by identity.
var ErrNotFound = errors.New("not found")

func findUser(id int) error {
	return ErrNotFound // pretend the row is missing
}

func getUser(id int) error {
	if err := findUser(id); err != nil {
		// %w wraps the cause, keeping it inspectable up the stack.
		return fmt.Errorf("getUser %d: %w", id, err)
	}
	return nil
}

func main() {
	err := getUser(42)
	fmt.Println("error:", err) // human-readable, includes context

	// errors.Is walks the chain; == would fail because err is wrapped.
	if errors.Is(err, ErrNotFound) {
		fmt.Println("matched ErrNotFound -> return 404")
	}
	fmt.Println("direct ==:", err == ErrNotFound) // false: outer != sentinel
}

package main

import (
	"errors"
	"fmt"
)

// QueryError is a structured error carrying a code and an inner cause.
type QueryError struct {
	Code  int
	Query string
	Err   error // wrapped cause
}

func (e *QueryError) Error() string {
	return fmt.Sprintf("query %q failed (code %d): %v", e.Query, e.Code, e.Err)
}

// Unwrap exposes the cause to errors.Is/As.
func (e *QueryError) Unwrap() error { return e.Err }

var ErrConn = errors.New("connection refused")

func runQuery() error {
	qe := &QueryError{Code: 503, Query: "SELECT 1", Err: ErrConn}
	// Wrap the structured error with more context.
	return fmt.Errorf("runQuery: %w", qe)
}

func main() {
	err := runQuery()

	var qe *QueryError
	if errors.As(err, &qe) { // extract the typed error from the chain
		fmt.Printf("got QueryError code=%d query=%s\n", qe.Code, qe.Query)
	}

	// errors.Is still finds the inner sentinel through both wrappers.
	if errors.Is(err, ErrConn) {
		fmt.Println("root cause is a connection error -> retryable")
	}
}
